"""Smoke test generated by ShipPilot.

Fails loudly until the project declares its own entry point, so an empty
pipeline cannot masquerade as a green one.
"""

import importlib
import os


def test_package_imports_or_is_declared():
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    declared = os.path.exists(os.path.join(root, "pyproject.toml")) or \
        os.path.exists(os.path.join(root, "setup.py")) or \
        os.path.exists(os.path.join(root, "requirements.txt"))
    assert declared, "declare dependencies so the pipeline can install them"

    for candidate in ("src", "app", "main", "service"):
        if os.path.exists(os.path.join(root, candidate + ".py")):
            importlib.import_module(candidate)
            return
    assert os.path.isdir(os.path.join(root, "src")), "no importable entry point found"
